	block.builders.claim.addLine(
		`${if_name}${name}.claim(${state.parentNodes});`
	);

	if (needsAnchor) {
		block.addElement(
			anchor,
			`@createComment()`,
			`@createComment()`,
			state.parentNode
		);
	}
