		block.builders.unmount.addBlock(deindent`
			var ${iteration} = ${head};
			while (${iteration}) {
				${iteration}.unmount();
				${iteration} = ${iteration}.next;
			}
		`);
	}

	block.builders.destroy.addBlock(deindent`
		var ${iteration} = ${head};
		while (${iteration}) {
			${iteration}.destroy(false);
			${iteration} = ${iteration}.next;
		}
