// Keep original discovery except explicitly recorded, unscored native failures.
const fs=require('fs'),path=require('path'),read=fs.readdirSync;
const environment=JSON.parse(fs.readFileSync(path.join(__dirname,'native-environment.json'),'utf8'));
const excluded=new Set(environment.excludedRuntimeSamples);
const canonical=p=>path.resolve(p).replace(/\\/g,'/').toLowerCase();
const samples=canonical(path.join(__dirname,'test/runtime/samples'));
fs.readdirSync=function(p,options){
  const entries=read.apply(this,arguments);
  return global.__sufficeNativeSuite==='runtime'&&typeof p==='string'&&canonical(p)===samples?entries.filter(e=>!excluded.has(typeof e==='string'?e:e.name)):entries;
};
require('./native-loader-base.cjs');
// Restore the legacy SourceMap write convention under pinned modern Node.
const fs=require('fs'),write=fs.writeFileSync;
fs.writeFileSync=function(file,data){
  const args=Array.prototype.slice.call(arguments);
  if(data&&typeof data==='object'&&data.constructor&&data.constructor.name==='SourceMap'&&typeof data.toString==='function')args[1]=data.toString();
  return write.apply(this,args);
};
exports.normalizeSourceMapPaths=function(text){
  if(!/^\s*\{/.test(text))return text;
  let value;try{value=JSON.parse(text);}catch{return text;}
  if(value.version!==3||!Array.isArray(value.sources)||typeof value.mappings!=='string')return text;
  const normalize=value=>typeof value==='string'?value.replace(/\\/g,'/'):value;
  value.sources=value.sources.map(normalize);
  for(const name of ['file','sourceRoot'])if(typeof value[name]==='string')value[name]=normalize(value[name]);
  return JSON.stringify(value);
};
// Adapt only the two audited historical CLI fixture implementations.
exports.adaptCliSource=function(source,{runtime,compat,cli}){
  const replaceOnce=(needle,replacement)=>{
    if(source.split(needle).length!==2)throw new Error('Unexpected native CLI fixture: '+needle);
    source=source.replace(needle,replacement);
  };
  replaceOnce('return str\n',"return __sufficeNormalizeMap(str)\n\t\t.replace(/(\\/\\* )([^\\n]*?)( generated by Svelte)/g, (_, a, p, b) => a + p.replace(/\\\\/g, '/') + b)\n");
  if(source.includes('shell.exec(')){
    const quote=p=>'"'+p.replace(/\\/g,'/')+'"';
    const launcher=quote(runtime)+' --max-old-space-size=384 --require '+quote(compat)+' '+quote(cli);
    replaceOnce('command.replace(/^svelte /, `node ${cli} `)',"command.replace(/^svelte /, "+JSON.stringify(launcher+' ')+')');
    // ShellJS returns code, not commandErr. A failed child must fail the test.
    replaceOnce('const { commandErr } = shell.exec(', 'const { code: commandErr } = shell.exec(');
    replaceOnce('done(commandErr);', "done(new Error('CLI command exited '+commandErr));");
  }else if(!source.includes('alias svelte='))throw new Error('Unaudited native CLI executor');
  // The original actual.forEach assertion silently accepts missing output files.
  replaceOnce('actual.forEach((a, i) => {',"assert.deepEqual(actual.map(a=>a.file).sort(), expected.map(e=>e.file).sort(), 'CLI output inventory mismatch');\n\t\t\tactual.forEach((a, i) => {");
  return "const __sufficeNormalizeMap=require('../../native-compat.cjs').normalizeSourceMapPaths;\n"+source;
};
